"""Supply current-material guidance and delivery cases while preserving native tools."""

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


SKILL_NAME = "store-result-handoff"
SKILL_SOURCE = "curator-capability"
SKILL_ASSET = "skills/store-result-handoff/SKILL.md"

GUIDANCE = """门店分析以当次工作规则和配套日报为准。
1. 读取本次相关完整规则、字段说明和数据；已有相同完整材料则复用，补齐所需截断。先确定字段、渠道、公式、期间及交付要求，换批次不沿用旧口径。计算前对照案例 D：分别确定本期和基期年月，按记录日期限定两期，确认实际纳入年月；排名和原因共用这两份数据，不能把文件边界当期间。
2. 对照案例 A：过程说明也只使用当次已核算的数字，连同年月、门店范围、渠道或合计标签一起沿用。解释若要新增渠道客单，先取得同口径分组金额和有效订单数；仅当分组可加总为合并口径时，在原有核算中用相应订单权重核对还原合并值。没有结果不临时补数。必需指标与拟保留辅助值尽量一次取得；极值按所述范围和指标的带符号值判断，不取绝对值、不借另一指标的排序。未核实的可选数字及依赖它的确定判断不补写。
3. 解释时对照案例 C：先写已核实的数字变化。缺少分组金额而保留价值或机制解释时，将条件假设、证据缺口和当次原文标记组成同一句，不先写成事实再给另一动因补标。
4. 交付时按案例 B，直接从已组成的完整结果句开始，后接带数字的原因和必要口径说明，不在前面再加完成说明或“按规则回复如下”。发现期间混算，重算并替换全部受影响结果，不只改标签。材料充分直接分析；核验不足仍交付有依据部分，具体说明必需项缺口，不用计划代替结果。"""


class StoreCapability(CapabilityStrategy):
    """Delegate registration and tools; supply cases alongside available skill catalogs."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        return (
            SkillContribution(
                name=SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": request.assets[SKILL_ASSET]},
                source="store-analysis scope and delivery cases derived from R1-R4",
            ),
        )

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        matches = [
            skill for skill in request.skills
            if skill.name == SKILL_NAME and skill.source == SKILL_SOURCE
        ]
        if len(matches) != 1:
            raise ValueError(
                f"required skill {SKILL_SOURCE}/{SKILL_NAME}: expected one entry, found {len(matches)}"
            )
        if not matches[0].available:
            raise ValueError(f"required skill {SKILL_SOURCE}/{SKILL_NAME} is unavailable")
        return CapabilitySelection(
            tools=None,
            skills=tuple(
                SkillSelection(
                    name=skill.name,
                    source=skill.source,
                    delivery=(
                        "body" if (skill.source, skill.name) == (SKILL_SOURCE, SKILL_NAME)
                        else "catalog"
                    ),
                )
                for skill in request.skills if skill.available
            ),
            guidance=GUIDANCE,
        )


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> StoreCapability:
    """Bind an inert dependency; leave task identity and session progress untouched."""
    return StoreCapability(registrar)
